 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[1][0]

    def runs_on_row(r):
        runs = []
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != bg and end - c > 1:
                runs.append((color, c, end))
            c = end
        return runs

    top_runs, bottom_runs = runs_on_row(0), runs_on_row(h - 1)
    if not top_runs or not bottom_runs:
        return out
    color, a, b = top_runs[0]
    color2, d, e = bottom_runs[0]
    if color != color2 or b - a != e - d:
        return out

    markers = [(r, c, grid[r][c]) for r in range(1, h - 1) for c in range(w)
               if grid[r][c] != bg]
    if not markers:
        return out
    r0, c0, mark = markers[0]

    # The marker lies on one of the bars' aligned columns. The matching
    # column on the opposite bar is joined all the way across the grid.
    if a <= c0 < b:
        selected_col = c0
        paired_col = d + (c0 - a)
        for r in range(1, r0):
            if grid[r][selected_col] == bg:
                out[r][selected_col] = mark
    elif d <= c0 < e:
        selected_col = c0
        paired_col = a + (c0 - d)
        for r in range(r0 + 1, h - 1):
            if grid[r][selected_col] == bg:
                out[r][selected_col] = mark
    else:
        return out

